/*!
 * Themeasy — FAQ Accordion
 *
 * Tiny behavior layer for the FAQ Accordion widget: toggles the open item
 * class and ARIA state. The open/close motion itself is pure CSS (grid
 * 0fr/1fr). Clicks are handled through a single document-level delegated
 * listener, so the widget stays interactive inside the Elementor editor
 * (where content is re-rendered constantly) without any preview wiring.
 *
 * init() adds the `--js` enhancement class that lets the CSS collapse the
 * closed panels — with no JS every answer stays visible (progressive
 * enhancement). Re-entrant and idempotent.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  window.Themeasy = window.Themeasy || {}
  window.Themeasy.faqAccordion = window.Themeasy.faqAccordion || {}

  const SELECTOR_WIDGET = '.tms-faq-accordion'
  const SELECTOR_TRIGGER = '.tms-faq-accordion__trigger'
  const CLASS_JS = 'tms-faq-accordion--js'
  const CLASS_OPEN = 'tms-faq-accordion__item--open'
  const CLASS_MULTIPLE = 'tms-faq-accordion--multiple'

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  /**
   * Sync a trigger's aria-expanded with its item's open class.
   *
   * @param {HTMLElement} item The .tms-faq-accordion__item element.
   */
  function syncAria(item) {
    const trigger = item.querySelector(SELECTOR_TRIGGER)
    if (!trigger) return

    trigger.setAttribute('aria-expanded', item.classList.contains(CLASS_OPEN) ? 'true' : 'false')
  }

  // ------------------------------------------------------------------------
  // Toggle (document-level delegation)
  // ------------------------------------------------------------------------

  /**
   * Toggle the item that owns a clicked trigger; in single-open mode the
   * sibling items of the same widget close first.
   *
   * @param {HTMLElement} trigger The clicked .tms-faq-accordion__trigger.
   */
  function toggleFromTrigger(trigger) {
    const item = trigger.closest('.tms-faq-accordion__item')
    const root = trigger.closest(SELECTOR_WIDGET)
    if (!item || !root) return

    const isOpen = item.classList.contains(CLASS_OPEN)

    if (!isOpen && !root.classList.contains(CLASS_MULTIPLE)) {
      root.querySelectorAll(':scope > .' + CLASS_OPEN).forEach(function (openItem) {
        openItem.classList.remove(CLASS_OPEN)
        syncAria(openItem)
      })
    }

    item.classList.toggle(CLASS_OPEN, !isOpen)
    syncAria(item)
  }

  function onDocumentClick(event) {
    const trigger = event.target.closest(SELECTOR_TRIGGER)
    if (!trigger) return

    toggleFromTrigger(trigger)
  }

  // Bind the delegated listener exactly once, regardless of how often the
  // module (re-)initializes.
  if (!window.Themeasy.faqAccordion.delegationBound) {
    document.addEventListener('click', onDocumentClick)
    window.Themeasy.faqAccordion.delegationBound = true
  }

  // ------------------------------------------------------------------------
  // Init (progressive enhancement)
  // ------------------------------------------------------------------------

  /**
   * Enhance every FAQ accordion in scope: adds the `--js` class that lets the
   * CSS collapse closed panels, and syncs ARIA state. Safe to re-run.
   *
   * @param {HTMLElement} [root] Optional scope — defaults to document.
   */
  window.Themeasy.faqAccordion.init = function (root) {
    const scope = root || document
    const widgets = scope.querySelectorAll(SELECTOR_WIDGET)
    if (!widgets.length) return

    widgets.forEach(function (widget) {
      widget.classList.add(CLASS_JS)
      widget.querySelectorAll('.tms-faq-accordion__item').forEach(syncAria)
    })
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WIDGET)) {
      window.Themeasy.faqAccordion.init()
    }
  }

  window.Themeasy.faqAccordion.boot = boot

  onDomReady(boot)
})(window, document)
